import { getUserContext } from '@/lib/supabase/user-context'
import { createClient } from '@/lib/supabase/server'
import { PortalHeader, StatCard, PortalTable, EmptyState, StatusPill, formatDate } from '@/components/portal/portal-shell'

export default async function PortalAttendancePage() { const context = await getUserContext(); const supabase = await createClient(); const { data: profile } = await supabase.from('profiles').select('student_id').eq('id', context!.userId).maybeSingle(); const { data: links } = await supabase.from('parent_student_links').select('student_id').eq('parent_profile_id', context!.userId); const ids = [...new Set([...(links ?? []).map((x) => x.student_id), ...(profile?.student_id ? [profile.student_id] : [])])]; const { data } = ids.length ? await supabase.from('attendance').select('date,status').in('student_id', ids).order('date', { ascending: false }) : { data: [] as { date: string; status: string }[] }; const rows = data ?? []; const present = rows.filter((x) => x.status === 'present').length; const absent = rows.filter((x) => x.status === 'absent').length; const late = rows.filter((x) => x.status === 'late').length; const percent = rows.length ? Math.round((present / rows.length) * 100) : 0; return <><PortalHeader title="Attendance" description="Read-only attendance history for your linked student records." /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatCard label="Attendance" value={`${percent}%`} /><StatCard label="Present" value={String(present)} /><StatCard label="Absent" value={String(absent)} /><StatCard label="Late" value={String(late)} /></div><div className="mt-6">{rows.length ? <PortalTable headers={['Date', 'Status']} rows={rows.map((row) => [formatDate(row.date), <StatusPill key={row.date}>{row.status}</StatusPill>])} /> : <EmptyState text="No attendance records are available yet." />}</div></> }
